function field(key:string):PlanField {return [...options.value?.itemFields||[],...options.value?.moldFields||[]].find(f=>f.key===key)||{key,label:({moldName:'模具名称',engravedCode:'原刻码',brandId:'品牌',compatibilityEvidence:'适配确认依据'} as Record<string,string>)[key]||key,kind:'text',group:'engineering',maxLength:255}}
function editable(f:PlanField) {if(f.key==='quoteConfirmed')return !!options.value?.canConfirmQuote;if(f.key.startsWith('quote'))return !!options.value?.canWriteQuote;return !!options.value?.writableGroups.some(group=>group===f.group)}
