async function completedLifecycle(result:unknown){const state=result as {status?:string};if(state.status==='deleted'&&lifecycleKind.value==='item'){detailVisible.value=false;detail.value=undefined}lifecycleRecord.value=undefined;workspace.changed();await refresh()}

