async function loadContextPhone(){const id=Number(route.query.phoneModelId),token=user.token;contextPhone.value=undefined;if(!id)return;try{const phones=await referenceApi.getPhoneModelOptions([id]);if(token===user.token&&Number(route.query.phoneModelId)===id)contextPhone.value=phones[0]}catch{if(token===user.token)error.value='待关联手机读取失败，请刷新后核对'}}
