async function openDetail(id:number,tab='master',focus?:CollaborationRow){detailVisible.value=true;detailTab.value=tab;detail.value=undefined;focusedSet.value=focus?.itemId===id?focus:undefined;await loadDetail(id);await nextTick();if(focus&&detailTab.value==='sets')detailCanvas.value?.querySelector<HTMLElement>(`[data-mold-set-id="${focus.moldSetId}"]`)?.scrollIntoView?.({block:'start'})}
async function openRouteDetail(){const token=user.token,path=route.fullPath,itemId=Number(route.query.itemId),setId=Number(route.query.moldSetId);const tab=['master','sets','references'].includes(String(route.query.tab))?String(route.query.tab):setId?'sets':'master';try{if(setId){const row=await api.getMold(setId);if(token!==user.token||path!==route.fullPath)return;if(itemId&&row.itemId!==itemId)throw new Error('指定实物套不属于该模具档案，请核对链接');await openDetail(row.itemId,tab,row)}else if(itemId)await openDetail(itemId,tab)}catch(e){if(token===user.token&&path===route.fullPath)error.value=e instanceof Error?e.message:'模具定位失败，请重试'}}
watch(detailTab,async tab=>{if(!master.value)return;const id=master.value.itemId,token=user.token;auxLoading.value=true;try{if(tab==='references'){const r=await api.getMoldMasterHistory(id,1);if(token===user.token&&master.value?.itemId===id){historyRows.value=r.content;historyTotal.value=r.totalElements;historyPage.value=1}}if(tab==='references'){const r=await api.getMoldMasterReferences(id);if(token===user.token&&master.value?.itemId===id)references.value=r}}catch{if(token===user.token)error.value='关联资料加载失败'}finally{if(token===user.token)auxLoading.value=false}})
