async function partCorrection(row:CollaborationRow,key:string){if(!options.value?.administrator)return;try{const r=await ElMessageBox.prompt(uiText('仅更正资料录入，不改变实物刻码。'),uiText('完整部件原码更正'),{inputValue:String(value(row,key)||'')});const reason=await ElMessageBox.prompt(uiText('请说明更正依据。'),uiText('更正原因'),{inputType:'textarea',inputValidator:v=>!!v?.trim()||uiText('必须填写原因')});drafts.set(row,key,r.value.trim());const d=drafts.rows.get(rowKey(row));if(d)d.reason=reason.value.trim()}catch{}}
async function explain(row:CollaborationRow){try{const r=await ElMessageBox.prompt(uiText('填写修改原因或核对依据。'),uiText('更正 / 核对说明'),{inputType:'textarea',inputValue:drafts.rows.get(rowKey(row))?.reason||''});const d=drafts.rows.get(rowKey(row));if(d)d.reason=r.value.trim()}catch{}}
const inventoryVisible=ref(false),inventoryRow=ref<CollaborationRow>(),inventoryPart=ref('pc')
function openInventory(row:CollaborationRow,part:string){inventoryRow.value=row;inventoryPart.value=part;inventoryVisible.value=true}
function stageInventory(selected:api.MoldInventoryOption,reason:string){const row=inventoryRow.value,part=inventoryPart.value;if(!row)return;const original=value(row,part+'OriginalMoldCode')||row[part+'CatalogMoldCode']||row[part+'MoldCode'];const catalog=row[part+'CatalogMoldCode']||row[part+'MoldCode'];if((master.value?.engravedCodeConfirmed&&original!==selected.inventoryCode)||(value(row,part+'MoldCodeId')&&catalog&&catalog!==selected.inventoryCode)){ElMessage.warning(uiText('来源原码与已确认刻码或编码关系不同，请核对，不自动替换刻码'));return}drafts.set(row,part+'InventoryId',selected.inventoryId);if(!master.value?.engravedCodeConfirmed)drafts.set(row,part+'OriginalMoldCode',selected.inventoryCode);const d=drafts.rows.get(rowKey(row));if(d)d.reason=reason;inventoryVisible.value=false}
async function unlinkInventory(row:CollaborationRow,part:string){try{const r=await ElMessageBox.prompt(uiText('只解除来源关联，不删除库存或原码。请填写原因。'),uiText('解除来源关联'),{inputType:'textarea',inputValidator:v=>!!v?.trim()||uiText('必须填写原因')});drafts.set(row,part+'InventoryId',null);const d=drafts.rows.get(rowKey(row));if(d)d.reason=r.value.trim()}catch{}}
const reviewVisible=ref(false)
async function save(){const patches=scopes.flatMap(scope=>drafts.patches(scope));if(!patches.length)return;const token=user.token;saving.value=true;error.value='';let saved=0,failed=0;try{for(let i=0;i<patches.length;i+=100){if(token!==user.token)return;const submitted=patches.slice(i,i+100),results=await api.saveMolds(submitted);if(token!==user.token)return;for(const r of results){drafts.apply(r,submitted.find(p=>p.entityType===r.entityType&&p.id===r.id));if(r.status==='saved')saved++;else failed++}}if(saved){workspace.changed();await refresh();ElMessage.success(uiText('已保存 {value0} 条模具资料',{value0:(saved)}))}if(failed){error.value=`${failed} 条未保存，草稿保留，请核对错误或冲突`;reviewVisible.value=true}else reviewVisible.value=false}catch{if(token===user.token)error.value='保存未完成，未确认成功的草稿已保留'}finally{saving.value=false}}
async function discard(){if(!dirtyCount.value)return;try{await ElMessageBox.confirm(uiText('只撤销模具资料、位置和报价修改；其他入口的日期、市场、产量草稿保留。'),uiText('撤销模具草稿'));scopes.forEach(scope=>drafts.clear(scope));error.value=''}catch{}}
function navigate(path:string,set?:CollaborationRow){return router.push({path,query:{...(master.value?{itemId:master.value.itemId}:{}),...(set?.moldSetId?{moldSetId:set.moldSetId}:{})}})}
