const referenceVisible=ref(false),sourceVisible=ref(false),sourceVisited=ref(false)
const createVisible=ref(false),creating=ref(false),createError=ref(''),copySource=ref<CollaborationRow>(),copyPhoneIds=ref<number[]>([]),copyReason=ref(''),copyRequestId=ref(''),copyFrozen=ref(false),createForm=ref({productLineId:undefined as number|undefined,moldName:'',engravedCode:'',compatibleModels:'',brandId:undefined as number|undefined})
function openCreate(){createError.value='';copySource.value=undefined;createForm.value={productLineId:undefined,moldName:'',engravedCode:'',compatibleModels:'',brandId:undefined};createVisible.value=true}
function copy(row:CollaborationRow){if(row.schedulePaused){ElMessage.warning(uiText('来源申请已暂停，请先处理执行状态'));return}if(drafts.rows.has(rowKey(row))){ElMessage.warning(uiText('请先保存或撤销来源套草稿'));return}createError.value='';copySource.value=row;const phones=relations.value.filter(r=>phoneSetCompatibilities(r).some(s=>s.moldSetId===row.moldSetId)).map(r=>r.phoneModelId);copyPhoneIds.value=phones.length===1?phones:[];copyReason.value='';copyRequestId.value=crypto.randomUUID();copyFrozen.value=false;createVisible.value=true}
async function create(){
  if(creating.value)return
  createError.value=''
  const token=user.token
  if(!copySource.value){
    if(!createForm.value.productLineId){createError.value='请选择产品款式';return}
    if(!createForm.value.moldName.trim()){createError.value='请填写模具名称';return}
    if(!createForm.value.compatibleModels.trim()){createError.value='请填写原始兼容型号文字';return}
  }
  creating.value=true
  try{
    if(copySource.value){
      if(copyPhoneIds.value.length!==1||!copyReason.value.trim()){ElMessage.warning(uiText('请选择一款标准手机并填写新增套／重新开模原因'));return}
      copyFrozen.value=true
      const application=await startMoldApplication({phoneModelId:copyPhoneIds.value[0]!,productLineId:copySource.value.productLineId,executionIntent:'new_set',targetItemId:copySource.value.itemId,executionReason:copyReason.value.trim(),newApplication:true,requestId:copyRequestId.value})
      if(token!==user.token)return
      if(!application.applicationId)throw new Error('申请尚未建立，请核对已有申请')
      createVisible.value=false;detailVisible.value=false;workspace.changed()
      await router.push({path:'/market-watch',query:{applicationId:application.applicationId,edit:'1'}})
      return
    }
    const p=createForm.value.productLineId!
    const platform=options.value?.productLines.find(l=>l.productLineId===p)
    const r=await api.createMoldMaster({...createForm.value,productLineId:p,styleName:platform?.productName||'',moldName:createForm.value.moldName.trim(),compatibleModels:createForm.value.compatibleModels.trim()})
    if(token!==user.token)return
    await openDetail(r.itemId)
    if(token===user.token){createVisible.value=false;workspace.changed();await refresh()}
  }catch(e){if(token===user.token)createError.value=partnerError(e)}
  finally{creating.value=false}
}
async function createSet(){if(!master.value||!engineer.value)return;const itemId=master.value.itemId,token=user.token;try{const name=await ElMessageBox.prompt(uiText('仅登记已经存在的实物；新制作请从实物卡片发起开模申请。'),uiText('登记已有实物'),{inputValue:''});if(token!==user.token)return;const evidence=await ElMessageBox.prompt(uiText('填写实物已存在的事实依据（位置、原刻码、历史记录等），后续仍需逐部件核对。'),uiText('已有实物登记依据'),{inputType:'textarea',inputValidator:v=>!!v?.trim()||uiText('必须填写事实依据')});if(token!==user.token)return;await api.createMold(itemId,name.value,evidence.value.trim());if(token!==user.token)return;workspace.changed();await refresh()}catch(e){if(e!=='cancel'&&e!=='close'&&token===user.token){error.value=e instanceof Error?e.message:'登记实物失败，请重试';ElMessage.error(error.value)}}}
function applyRoute(){if(route.path!=='/molds')return;void loadContextPhone();itemFilter.value=Number(route.query.itemId)||undefined;productLineId.value=Number(route.query.productLineId)||undefined;if(typeof route.query.keyword==='string')keyword.value=route.query.keyword;if(route.query.panel==='reference-data')referenceVisible.value=true;reset();if(mounted)void openRouteDetail()}
watch(()=>route.fullPath,applyRoute)
watch(()=>user.token,()=>{generation++;request.clear();request.data.value=undefined;request.hasCurrentData.value=false;detail.value=undefined;focusedSet.value=undefined;detailVisible.value=false;options.value=undefined;brands.value=[];historyRows.value=[];references.value=undefined;memberOptions.value=[];contextPhone.value=undefined;referenceVisible.value=false;sourceVisible.value=false;createVisible.value=false;createError.value='';reviewVisible.value=false;inventoryVisible.value=false;inventoryRow.value=undefined;lifecycleRecord.value=undefined},{flush:'sync'})
function beforeUnload(event:BeforeUnloadEvent){if(drafts.rows.size){event.preventDefault();event.returnValue=''}}
onBeforeRouteLeave(async to=>{if(!dirtyCount.value)return true;const shared=isCollaborationEntry(to.path);try{await ElMessageBox.confirm(shared?uiText('未保存的模具草稿将保留，前往关联入口？'):uiText('仍有模具草稿，离开将撤销当前模块草稿。'),uiText('未保存修改'));if(!shared)scopes.forEach(scope=>drafts.clear(scope));return true}catch{return false}})
onMounted(async()=>{window.addEventListener('beforeunload',beforeUnload);const token=user.token;try{const [o,b]=await Promise.all([api.getMoldOptions(),referenceApi.getPhoneBrands({page:1,size:100})]);if(token!==user.token)return;options.value=o;brands.value=b.content;applyRoute();await load();mounted=true;await openRouteDetail()}catch{if(token===user.token)error.value='初始化失败，请刷新重试'}})
onActivated(()=>{active=true;if(mounted){void load();if(detailVisible.value&&detail.value)void loadDetail(detail.value.master.itemId,setsPage.value)}});onDeactivated(()=>{active=false;clearTimeout(timer);request.invalidate()});onBeforeUnmount(()=>{clearTimeout(timer);generation++;window.removeEventListener('beforeunload',beforeUnload)})
</script>

<template>
  <main ref="canvas" class="mold-management"><header class="toolbar"><h2>{{ uiText("模具管理") }}</h2><div class="actions"><el-button size="small" @click="openPhoneCodes()">{{ uiText("手机编码资料") }}</el-button><el-button size="small" @click="sourceVisited=true;sourceVisible=true">{{ uiText("编码来源核对") }}</el-button><el-button size="small" @click="refresh">{{ uiText("刷新") }}</el-button><el-button v-if="engineer" size="small" type="primary" @click="openCreate">{{ uiText("新增共模档案") }}</el-button></div></header>
    <div class="filters"><el-input v-model="keyword" size="small" clearable :placeholder='uiText("搜索模具名称 / 原刻码 / 手机 / 厂家")'/><el-select v-model="productLineId" size="small" clearable :placeholder='uiText("全部款式")'><el-option v-for="p in options?.productLines" :key="p.productLineId" :value="p.productLineId" :label="p.productName"/></el-select><el-select v-model="brandId" size="small" clearable :placeholder='uiText("全部品牌")'><el-option v-for="b in brands" :key="b.brandId" :value="b.brandId" :label="b.name"/></el-select><el-select v-model="stockState" size="small" clearable :placeholder='uiText("全部库存状态")'><el-option value="pending" :label='uiText("待核对")'/><el-option value="making" :label='uiText("在制")'/><el-option value="partial" :label='uiText("部分实物")'/><el-option value="confirmed" :label='uiText("已确认实物")'/></el-select><el-select v-model="location" size="small" clearable :placeholder='uiText("全部位置")'><el-option v-for="(label,key) in locationNames" :key="key" :value="key" :label="label"/></el-select><span class="count">{{ uiText("共 ") }}{{total}}{{ uiText(" 个共模档案") }}</span></div>
    <el-alert v-if="route.query.phoneModelId" type="info" :closable="false" :title="uiText('待关联手机：{value0}。请打开共模档案，明确选择手机、适用实物套及 PC／TPU 确认；此入口不会自动建立关系。',{value0:(contextPhone?phoneName(contextPhone):'资料 #'+route.query.phoneModelId)})"/><el-alert v-if="error||request.error.value" :title="error||request.error.value" type="error" :closable="false"/>
    <section class="master-list" :class="{'is-narrow':narrow,'is-small':smallNarrow}" v-loading="request.loading.value" :aria-label='uiText("共模档案总表")'><div v-if="!narrow" class="master-grid table-head"><span>{{ uiText("模具名称") }}</span><span>{{ uiText("原刻码") }}</span><span>{{ uiText("款式") }}</span><span>{{ uiText("品牌") }}</span><span>{{ uiText("兼容手机型号") }}</span><span>{{ uiText("模具实物库存") }}</span><span>{{ uiText("每套制模报价") }}</span><span>{{ uiText("位置概况") }}</span><span>{{ uiText("制模厂家") }}</span><span>{{ uiText("操作") }}</span></div><article v-for="row in rows" :key="row.itemId" class="master-grid master-row" :data-item-id="row.itemId"><div data-label="模具名称"><button class="master-link" @click="openDetail(row.itemId)">{{name(row)}}</button><el-tag v-if="row.masterDataStatus==='inactive'" size="small" type="info">{{ uiText("已停用") }}</el-tag></div><div data-label="原刻码"><button class="master-link code" @click="openDetail(row.itemId)">{{value(row,'engravedCode')||uiText('待确认')}}</button><span v-if="!row.engravedCodeConfirmed" class="subtle">{{ uiText("待核对") }}</span></div><div data-label="款式">{{archivePlatformName(row)}}</div><div data-label="品牌">{{brandLabel(row)}}</div><div data-label="兼容手机型号"><template v-if="row.members?.length"><span v-for="p in row.members" :key="p.phoneModelId" class="member">{{phoneName(p)}} <small>{{p.phoneModelCode||uiText('编码待分配')}}</small></span></template><span v-else>{{row.compatibleModels||uiText('待关联')}}</span></div><div data-label="模具实物库存">{{stock(row.summary)}}<small class="subtle">{{ uiText("在制 ") }}{{row.summary.makingSets}} · <button v-if="row.summary.pendingSets" class="master-link" :aria-label='uiText("核对本档待核对实物")' @click="openDetail(row.itemId,'sets')">{{ uiText("待核对 ") }}{{row.summary.pendingSets}}{{ uiText(" · 核对实物") }}</button><span v-else>{{ uiText("待核对 0") }}</span></small></div><div data-label="每套制模报价">{{quote(row.summary)}}</div><div data-label="位置概况">{{row.summary.locations?.map(l=>locationNames[l]||l).join(' / ')||uiText('未知')}}</div><div data-label="制模厂家">{{row.summary.manufacturers?.join(' / ')||uiText('未填写')}}</div><div data-label="操作" class="lifecycle-actions"><el-button size="small" link @click="openDetail(row.itemId)">{{ uiText("详情／编辑") }}</el-button><template v-if="engineer"><el-button size="small" link @click="lifecycle(row,'item',row.masterDataStatus==='inactive'?'activate':'deactivate')">{{row.masterDataStatus==='inactive'?uiText('启用'):uiText('停用')}}</el-button><el-button size="small" link type="danger" @click="lifecycle(row,'item','delete')">{{ uiText("删除") }}</el-button></template></div></article><el-empty v-if="!rows.length&&!request.loading.value" :description='uiText("暂无匹配共模档案")'/></section>
    <div v-if="dirtyCount" class="save-dock"><span>{{dirtyCount}}{{ uiText(" 个模具字段待保存 ") }}<el-button link size="small" @click="reviewVisible=true">{{ uiText("核对修改") }}</el-button></span><div><el-button size="small" @click="discard">{{ uiText("撤销模具修改") }}</el-button><el-button size="small" type="primary" :loading="saving" data-test="save-molds" @click="save">{{ uiText("批量保存") }}</el-button></div></div>
    <el-pagination v-model:current-page="page" v-model:page-size="size" :page-sizes="[20,50,100]" :total="total" layout="total,sizes,prev,pager,next" @current-change="load()"/>
    <el-drawer v-model="detailVisible" :title='uiText("共模档案详情")' size="min(1240px,96vw)" :close-on-click-modal="false" class="mold-master-drawer"><div ref="detailCanvas" v-loading="detailLoading" class="detail-content"><el-alert v-if="detailError" :title="detailError" type="error" :closable="false" class="detail-error"><el-button size="small" @click="detailItemId&&loadDetail(detailItemId,setsPage)">{{ uiText("重试读取模具详情") }}</el-button></el-alert><template v-if="master&&options"><div class="detail-head"><strong>{{name(master)}}</strong><span>{{ uiText("原刻码 ") }}{{value(master,'engravedCode')||uiText('待确认')}}{{ uiText(" · 档案 #") }}{{master.itemId}}</span><el-tag v-if="master.masterDataStatus==='inactive'" size="small" type="info">{{ uiText("已停用") }}</el-tag><template v-if="engineer"><el-button size="small" @click="lifecycle(master,'item',master.masterDataStatus==='inactive'?'activate':'deactivate')">{{master.masterDataStatus==='inactive'?uiText('启用'):uiText('停用')}}</el-button><el-button size="small" type="danger" plain @click="lifecycle(master,'item','delete')">{{ uiText("引用／删除主档") }}</el-button></template></div><el-tabs v-model="detailTab"><el-tab-pane name="master" :label='uiText("模具资料与兼容手机")'/><el-tab-pane name="sets" :label='uiText("实物库存与报价")'/><el-tab-pane name="references" :label='uiText("关联与历史")'/></el-tabs><p v-if="!engineer" class="hint detail-permission">{{ uiText("当前账号没有工程维护权限，适配、原刻码及实物核对状态只读；请由具有工程权限的人员处理。") }}</p>
      <section v-if="detailTab==='master'" class="master-form"><div v-if="contextPhone" class="full context-review"><strong>{{ uiText("本次待核对：") }}{{phoneName(contextPhone)}}</strong><p class="hint">{{ uiText("明确加入本档后，在下方选择适用实物套，分别填写 PC／TPU 适配依据；不会自动确认。") }}</p><el-button size="small" @click="detailTab='sets'">{{ uiText("核对原刻码与实物状态") }}</el-button></div><label><span>{{ uiText("模具名称") }}</span><CollaborationCell :field="field('moldName')" :value="value(master,'moldName')" :editable="engineer" :dirty="dirty(master,'moldName')" @preview="edit(master,field('moldName'),$event,true)" @edit="edit(master,field('moldName'),$event)"/></label><label><span>{{ uiText("原刻码（实物刻码，不随兼容成员改动）") }}</span><CollaborationCell :field="field('engravedCode')" :value="value(master,'engravedCode')" :editable="engineer&&!master.engravedCodeConfirmed" :dirty="dirty(master,'engravedCode')" @preview="edit(master,field('engravedCode'),$event,true)" @edit="edit(master,field('engravedCode'),$event)"/><el-checkbox :model-value="!!value(master,'engravedCodeConfirmed')" :disabled="!engineer||master.engravedCodeConfirmed" @change="setBoolean('engravedCodeConfirmed',$event)">{{ uiText("确认原刻码并锁定") }}</el-checkbox><el-button v-if="master.engravedCodeConfirmed&&options.administrator" link @click="codeCorrection">{{ uiText("更正录入错误") }}</el-button><p v-if="master.engravedCodeConfirmed" class="hint">{{ uiText("原刻码已确认，适配核对无需改刻码；录入错误由管理员使用更正入口并记录原因。") }}</p></label><label><span>{{ uiText("产品款式") }}</span><p>{{archivePlatformName(master)}}</p></label><div class="shared-brand"><span>{{ uiText("品牌（共用手机编码资料）") }}</span><strong>{{brandLabel(master)}}</strong><p class="hint">{{ uiText("品牌与手机编码共用，无需重复关联。") }}</p><p v-if="master.brandSourceDetail" class="hint">{{master.brandSourceDetail}}</p><p v-if="master.brandConflict" class="hint brand-conflict">{{ uiText("历史档案品牌与共享资料不同，当前按共享资料显示；原始记录保留。") }}</p><el-button size="small" link @click="openPhoneCodes(master)">{{ uiText("查看来源资料") }}</el-button><details v-if="engineer" class="brand-correction"><summary>{{ uiText("补充 / 更正历史档案品牌") }}</summary><p class="hint">{{ uiText("未关联共享资料的历史档案可在此补充；已有关联时，以标准手机及编码组品牌为准。") }}</p><el-select :model-value="value(master,'brandId')" :aria-label='uiText("历史档案品牌")' clearable filterable @update:model-value="drafts.set(master,'brandId',$event||null)"><el-option v-for="b in brands" :key="b.brandId" :label="b.name" :value="b.brandId"/></el-select></details></div><label class="full"><span>{{ uiText("兼容手机成员（同码或不同码均可共模）") }}</span><SharedCompatiblePhoneSelector v-model="selectedPhones" :members="selectorMembers" :review-phone-id="contextPhone?.phoneModelId" :disabled="!engineer" :allow-manage="false" @selected="memberOptions=$event"/></label><div class="full"><CompatiblePhoneRelations :relations="reviewRelations" :members="selectorMembers" :sets="detail?.setOptions||(detail?.sets.content||[]).map(s=>({moldSetId:s.moldSetId!,assetNumber:s.assetNumber!,setNo:s.setNo!}))" :editable="engineer" :dirty="dirty(master,'compatiblePhones')" @update="updateRelation"/></div><div class="full original"><strong>{{ uiText("原始资料（不改写历史快照）") }}</strong><p>{{master.styleName}} / {{master.compatibleModels}}{{ uiText(" · 原型号编码 ") }}{{master.phoneModelCode||uiText('未知')}}{{ uiText(" · 原始品牌 ") }}{{master.brand||uiText('未填写')}}</p></div></section>
      <section v-else-if="detailTab==='sets'"><div v-for="s in detail?.sets.content.filter(row=>row.applicationLinks?.length||row.schedulePaused)" :key="'application-'+s.moldSetId" class="reference-row"><span>{{s.assetNumber}} · {{s.schedulePaused?uiText('已暂停'):s.applicationPlanned?uiText('待开工'):uiText('实物套')}}</span><div><el-button v-for="a in s.applicationLinks" :key="a.applicationId" size="small" link @click="router.push({path:'/mold-applications',query:{applicationId:a.applicationId}})">{{ uiText("查看申请 ") }}{{a.approvalNo||`#${a.applicationId}`}}</el-button></div></div><div class="section-tools"><span>{{stock(detail!.summary)}}{{ uiText("；登记 ") }}{{detail!.summary.registeredSets}}{{ uiText(" 套 / 待核对 ") }}{{detail!.summary.pendingSets}}{{ uiText(" 套") }}</span><el-button v-if="engineer" size="small" @click="createSet">{{ uiText("登记已有实物") }}</el-button></div><section v-for="s in physicalRows" :key="s.moldSetId" class="physical-lifecycle"><header class="section-tools"><span>{{s.assetNumber||s.setName}} · {{s.setMasterDataStatus==='inactive'?uiText('已停用'):uiText('在用')}}</span><div v-if="engineer" class="lifecycle-actions"><el-button size="small" @click="lifecycle(s,'mold_set',s.setMasterDataStatus==='inactive'?'activate':'deactivate')">{{s.setMasterDataStatus==='inactive'?uiText('启用'):uiText('停用')}}</el-button><el-button size="small" type="danger" plain @click="lifecycle(s,'mold_set','delete')">{{ uiText("引用／删除此套") }}</el-button></div></header><MoldPhysicalEditor :row="{...s,members:selectorMembers,compatiblePhones:relations}" :review-target="s.moldSetId===focusedSet?.moldSetId" :options="options" :locked="master.engravedCodeConfirmed" :value="value" :dirty="dirty" @preview="(row:CollaborationRow,f:PlanField,text:string)=>edit(row,f,text,true)" @edit="edit" @copy="copy" @reason="explain" @correction="partCorrection" @inventory="openInventory" @unlink="unlinkInventory"/></section><el-pagination v-model:current-page="setsPage" :page-size="50" :total="detail!.sets.totalElements" layout="total,prev,pager,next" @current-change="loadDetail(master.itemId,setsPage)"/><el-empty v-if="!physicalRows.length" :description='uiText("暂无确认的实物套；不从资料数量自动建套")'/></section>
      <section v-else-if="detailTab==='references'" v-loading="auxLoading"><h4>{{ uiText("关联项目") }}</h4><div v-for="p in references?.item.projects" :key="p.projectId" class="reference-row"><span>{{p.productName}} · {{p.productCode}}</span><el-button link @click="router.push({path:'/projects',query:{productId:p.projectId}})">{{ uiText("查看项目 / 附件") }}</el-button></div><h4>{{ uiText("历史运模资料") }}</h4><div v-for="e in references?.expressRecords" :key="e.projectId+':'+e.trackingNo" class="reference-row"><span>{{e.trackingNo}} · {{e.latestStatusText||uiText('无状态')}}</span><el-button link @click="router.push({path:'/projects',query:{productId:e.projectId}})">{{ uiText("查看原记录") }}</el-button></div><p class="hint">{{ uiText("快递记录仅作关联资料，不自动判定实物库存或验收完成。") }}</p></section>
      <section v-if="detailTab==='references'" v-loading="auxLoading"><h4>{{ uiText("修改历史") }}</h4><article v-for="h in historyRows" :key="h.historyId" class="history-row"><strong>{{uiText(String((field(h.fieldName).label) ?? ''))}}</strong><p>{{display(h.before)}} → {{display(h.after)}}</p><small>{{h.actorName}} · {{h.changedAt}} · {{h.reason||uiText('无修改说明')}}</small></article><el-pagination v-model:current-page="historyPage" :page-size="20" :total="historyTotal" layout="total,prev,pager,next" @current-change="loadHistory"/></section>
    </template></div><template #footer><div class="drawer-footer"><div><el-button v-if="master && user.hasPermission('file:read')" @click="router.push({path:'/files',query:{referenceType:'item',referenceId:master.itemId,referenceName:master.moldName,referenceCode:master.engravedCode}})">{{ uiText("查看关联图纸") }}</el-button><el-button v-if="master" @click="router.push({path:'/mold-schedules',query:{tab:'applications',productLineId:master.productLineId}})">{{ uiText("查看申请进度") }}</el-button><el-button @click="navigate('/mold-schedules')">{{ uiText("开模时间管控") }}</el-button><el-button @click="openTasks">{{ uiText("处理待办") }}</el-button></div><div><el-button @click="detailVisible=false">{{ uiText("关闭（保留草稿）") }}</el-button><el-button type="primary" :loading="saving" :disabled="!dirtyCount" @click="save">{{ uiText("保存模具修改") }}</el-button></div></div></template></el-drawer>
    <el-drawer v-model="reviewVisible" :title='uiText("模具待保存与冲突核对")' size="min(1000px,96vw)"><section v-for="[key,d] in staged" :key="key" class="history-row"><strong>{{d.source.assetNumber||d.source.moldName||d.source.compatibleModels}}</strong><div v-for="[name,c] in d.changes" :key="name">{{uiText(String((field(name).label) ?? ''))}}：{{display(c.before)}} → {{display(c.after)}}</div><el-button link @click="explain(d.source)">{{ uiText("填写更正 / 核对说明") }}</el-button><p v-if="d.result">{{d.result.message}}</p><div v-for="c in d.result?.conflicts" :key="c.field" class="conflict"><span>{{uiText(String((c.label) ?? ''))}}{{ uiText(" 当前：") }}{{display(c.current)}}{{ uiText("；待保存：") }}{{display(c.attempted)}}</span><el-button size="small" @click="drafts.resolve(key,c.field,false)">{{ uiText("采用当前值") }}</el-button><el-button size="small" @click="drafts.resolve(key,c.field,true)">{{ uiText("确认保留我的修改") }}</el-button></div></section><template #footer><el-button @click="reviewVisible=false">{{ uiText("继续填写") }}</el-button><el-button type="primary" :loading="saving" @click="save">{{ uiText("保存已核对修改") }}</el-button></template></el-drawer>
    <el-dialog v-model="createVisible" :title="copySource?uiText('复制 / 重新开模'):uiText('新增共模档案')" width="min(780px,94vw)" :close-on-click-modal="false"><el-alert v-if="createError" class="create-error" :title="createError" type="error" :closable="false"/><template v-if="copySource"><p>{{ uiText("沿用原模具主档发起新增套申请；审批同意后登记待制作套。已有日期、位置和报价不复制。") }}</p><SharedCompatiblePhoneSelector v-model="copyPhoneIds" :multiple="false" :members="detail?.members||[]" :allow-manage="false" :disabled="copyFrozen"/><p class="hint">{{ uiText("请选择一款标准手机，多个候选不会自动选择。") }}</p><el-input v-model="copyReason" :disabled="copyFrozen" type="textarea" :rows="3" :aria-label='uiText("新增套申请原因")' :placeholder='uiText("新增套／重新开模原因")' maxlength="2000"/></template><el-form v-else class="create-form" label-position="top"><el-form-item :label='uiText("产品款式")' required><el-select v-model="createForm.productLineId" filterable :aria-label='uiText("产品款式")' :placeholder='uiText("请选择产品款式")'><el-option v-for="p in options?.productLines" :key="p.productLineId" :label="p.productName" :value="p.productLineId"/></el-select></el-form-item><el-form-item :label='uiText("模具名称")' required><el-input v-model="createForm.moldName" :aria-label='uiText("模具名称")' :placeholder='uiText("填写模具名称")'/></el-form-item><el-form-item :label='uiText("原刻码（未知可留空，后续核对）")'><el-input v-model="createForm.engravedCode" :aria-label='uiText("原刻码")'/></el-form-item><el-form-item :label='uiText("原始兼容型号文字")' required><el-input v-model="createForm.compatibleModels" :aria-label='uiText("原始兼容型号文字")' :placeholder='uiText("按原资料填写兼容手机型号")'/></el-form-item><p>{{ uiText("先建立档案，再核对实物与兼容成员；不自动生成编码或实物套。") }}</p></el-form><template #footer><el-button @click="createVisible=false">{{ uiText("取消") }}</el-button><el-button type="primary" :loading="creating" @click="create">{{copySource?(copyFrozen?uiText('重试同一申请'):uiText('发起申请草稿')):uiText('确认建立')}}</el-button></template></el-dialog>
    <MoldInventoryLinkDialog v-model="inventoryVisible" :part="inventoryPart" @stage="stageInventory"/>
    <MasterDataLifecycleDialog :record="lifecycleRecord" :kind-label="lifecycleKind==='item'?'模具主档':'模具实物套'" :action="lifecycleAction" :editable="engineer" :context="`${user.token}:${lifecycleKind}`" :load="inspectLifecycle" :perform="performLifecycle" @close="lifecycleRecord=undefined" @completed="completedLifecycle" @open="path=>router.push(path)"/>
    <PhoneReferenceManager v-model="referenceVisible" :editable="engineer" :keyword="typeof route.query.keyword==='string'?route.query.keyword:undefined" @changed="refresh"/>
    <el-drawer v-model="sourceVisible" :title='uiText("模具编码来源核对")' size="min(1400px,96vw)"><MoldSourceCodes v-if="sourceVisited" :visible="sourceVisible" @close="sourceVisible=false"/></el-drawer>
  </main>
